def build_inclusion_proof(self, index: int) -> dict:
        """Build an RFC 9162 inclusion proof for the record at `index`."""
        if not (0 <= index < len(self._records)):
            raise IndexError(
                f"Index {index} out of range [0, {len(self._records)})"
            )
        leaves = [_digest_bytes(r["chain_hash"]) for r in self._records]
        proof_steps = rfc9162_inclusion_proof(leaves, index)
        root = rfc9162_merkle_root(leaves)
        return {
            "chain_hash": self._records[index]["chain_hash"],
            "proof": proof_steps,
            "merkle_root": "sha256:" + root.hex(),
        }

    def verify_inclusion_proof(self, proof: dict, merkle_root: str) -> bool:
        """Verify an inclusion proof against a given Merkle root.

        merkle_root should be in 'sha256:<hex>' format. If the proof embeds a
        merkle_root field, it must match the supplied root.
        """
        try:
            if "merkle_root" in proof and proof["merkle_root"] != merkle_root:
                return False
            leaf_data = _digest_bytes(proof["chain_hash"])
            root_bytes = _digest_bytes(merkle_root)
            return rfc9162_verify_inclusion(leaf_data, proof["proof"], root_bytes)
        except (KeyError, ValueError, TypeError):
            return False

def verify_bundle(self, bundle: EvidenceBundle) -> Tuple[bool, List[str]]:
        """Verify an evidence bundle's inclusion proofs against its Merkle root.

        Returns (all_valid, list_of_error_messages).
        """
        errors: List[str] = []

        # C0009/C0173/C0182: check list lengths match before iterating
        if len(bundle.records) != len(bundle.inclusion_proofs):
            errors.append(
                f"Length mismatch: {len(bundle.records)} records vs "
                f"{len(bundle.inclusion_proofs)} proofs"
            )
            return False, errors

        for i, (record, proof) in enumerate(
            zip(bundle.records, bundle.inclusion_proofs)
        ):
            # C0034/C0060/C0106: verify chain_hash matches before proof check
            record_hash = record.get("chain_hash", "")
            proof_hash = proof.get("chain_hash", "")
            if record_hash and proof_hash and record_hash != proof_hash:
                errors.append(
                    f"Record {i}: chain_hash mismatch "
                    f"(record={record_hash[:16]}... vs proof={proof_hash[:16]}...)"
                )
                continue

            valid = self._chain.verify_inclusion_proof(proof, bundle.merkle_root)
            if not valid:
                errors.append(
                    f"Record {i} (seq={record.get('sealed_body', {}).get('seq', '?')}): "
                    f"inclusion proof invalid"
                )
        return len(errors) == 0, errors

